import type { Metadata } from "next";
import { company } from "@/data/company";

export const siteUrl = company.url.replace(/\/$/, "");

export const baseKeywords = [
  "NBN installation Adelaide",
  "CCTV installation Adelaide",
  "NBN installer South Australia",
  "security camera installation Adelaide",
  "FTTP installation Adelaide",
  "NBN technician SA",
];

interface PageMetaInput {
  title: string;
  description: string;
  path: string;
  keywords?: string[];
}

/** Branded share image generated by src/app/opengraph-image.tsx */
const shareImage = { url: "/opengraph-image", width: 1200, height: 630, alt: `${company.name} – NBN & CCTV installation across South Australia` };

/**
 * Consistent metadata + Open Graph + Twitter tags for every page.
 * The share image is set explicitly because Next.js shallow-merges `openGraph`, so a
 * page that defines it would otherwise drop the root opengraph-image.
 */
export function buildMetadata({ title, description, path, keywords = [] }: PageMetaInput): Metadata {
  const url = `${siteUrl}${path === "/" ? "" : path}`;

  return {
    title,
    description,
    keywords: [...keywords, ...baseKeywords],
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "en_AU",
      siteName: company.name,
      title: `${title} | ${company.name}`,
      description,
      url,
      images: [shareImage],
    },
    twitter: {
      card: "summary_large_image",
      title: `${title} | ${company.name}`,
      description,
      images: [shareImage.url],
    },
  };
}

/** FAQPage structured data for rich results */
export function faqJsonLd(items: { question: string; answer: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: items.map((item) => ({
      "@type": "Question",
      name: item.question,
      acceptedAnswer: { "@type": "Answer", text: item.answer },
    })),
  };
}

/** Breadcrumb trail structured data */
export function breadcrumbJsonLd(trail: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: trail.map((item, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: item.name,
      item: `${siteUrl}${item.path === "/" ? "" : item.path}`,
    })),
  };
}

/** LocalBusiness schema built entirely from src/data/company.ts */
export function localBusinessJsonLd() {
  const sameAs = Object.values(company.social).filter(Boolean);
  return {
    "@context": "https://schema.org",
    "@type": ["LocalBusiness", "Electrician"],
    "@id": `${siteUrl}/#business`,
    name: company.name,
    legalName: company.legalName,
    description: company.description,
    url: siteUrl,
    telephone: company.phone.href.replace("tel:", ""),
    email: company.email,
    image: `${siteUrl}/opengraph-image`,
    logo: `${siteUrl}/icon.svg`,
    priceRange: "$$",
    foundingDate: String(company.foundedYear),
    taxID: company.abn,
    address: {
      "@type": "PostalAddress",
      streetAddress: company.address.street,
      addressLocality: company.address.suburb,
      addressRegion: company.address.state,
      postalCode: company.address.postcode,
      addressCountry: company.address.country,
    },
    geo: {
      "@type": "GeoCoordinates",
      latitude: company.address.geo.latitude,
      longitude: company.address.geo.longitude,
    },
    areaServed: company.serviceAreas.map((name) => ({ "@type": "Place", name: `${name}, South Australia` })),
    openingHoursSpecification: company.openingHours
      .filter((row) => row.schema)
      .map((row) => ({
        "@type": "OpeningHoursSpecification",
        dayOfWeek: row.schema!.dayOfWeek,
        opens: row.schema!.opens,
        closes: row.schema!.closes,
      })),
    aggregateRating: {
      "@type": "AggregateRating",
      ratingValue: company.rating.value,
      reviewCount: company.rating.count,
    },
    sameAs,
  };
}
